    typealias SwiftType = AgentEventKindDto

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> AgentEventKindDto {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .started
        
        case 2: return .statusChanged
        
        case 3: return .textDelta
        
        case 4: return .toolRequested
        
        case 5: return .toolCompleted
        
        case 6: return .confirmationRequired
        
        case 7: return .stageStarted
        
        case 8: return .stageProgress
        
        case 9: return .stageCompleted
        
        case 10: return .inputRequired
        
        case 11: return .artifactCreated
        
        case 12: return .failed
        
        case 13: return .cancelled
        
        case 14: return .completed
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: AgentEventKindDto, into buf: inout [UInt8]) {
        switch value {
        
        
        case .started:
            writeInt(&buf, Int32(1))
        
        
        case .statusChanged:
            writeInt(&buf, Int32(2))
        
        
        case .textDelta:
            writeInt(&buf, Int32(3))
        
        
        case .toolRequested:
            writeInt(&buf, Int32(4))
        
        
        case .toolCompleted:
            writeInt(&buf, Int32(5))
        
        
        case .confirmationRequired:
            writeInt(&buf, Int32(6))
        
        
        case .stageStarted:
            writeInt(&buf, Int32(7))
        
        
        case .stageProgress:
            writeInt(&buf, Int32(8))
        
        
        case .stageCompleted:
            writeInt(&buf, Int32(9))
        
        
        case .inputRequired:
            writeInt(&buf, Int32(10))
        
        
        case .artifactCreated:
            writeInt(&buf, Int32(11))
        
        
        case .failed:
            writeInt(&buf, Int32(12))
        
        
        case .cancelled:
            writeInt(&buf, Int32(13))
        
        
        case .completed:
            writeInt(&buf, Int32(14))
        
